// Replays `fixtures/physic_scripted.txt` (generated by
// `Build/physic_fixture_harness/gen_physic.sh` from the original `UnPhysic.cpp`
// at 58a73d4) through the Rust port with a scripted services mock. The mock
// reproduces the harness hook draws, log text, and the real `setPhysics` /
// `FindBase` side effects, so every record's output words and log digest must
// match bit-for-bit.

#[path = "actor_services/mock.rs"]
mod actor_services_mock;

use std::cell::{Cell, RefCell};
use std::collections::BTreeMap;
use std::ffi::c_void;
use std::ptr::null_mut;

use hp2_abi::FVector;
use hp2_abi::engine::generated::{
    AActor, ACarcass, ADecoration, APawn, AZoneInfo, FCheckResult, FRotator,
};
use hp2_engine::actor::CT_SHAPE;
use hp2_engine::physic::{self, Hp2PhysicServices};

const ARG0: usize = 56;
const OUT_WORDS: usize = 51;
const TRACE_ALL_BLOCKING: i32 = 1;
const FN_NAMES: [&str; 5] = [
    "calc_velocity",
    "mount",
    "step_up",
    "process_hit_wall",
    "process_landed",
];

#[derive(Default)]
struct Scene {
    svc: u64,
    log: String,
    subj: usize,
    subj_class: u32,
    zone: usize,
    pool: [usize; 3],
    pool_class: [u32; 3],
    motion_action: u32,
    motion_mover_pool: [bool; 3],
    trailer_bone_coords: [f32; 12],
}

thread_local! {
    static SCENE: RefCell<Scene> = RefCell::new(Scene::default());
}

fn with<R>(f: impl FnOnce(&mut Scene) -> R) -> R {
    SCENE.with(|s| f(&mut s.borrow_mut()))
}

fn sm_next(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
    let mut z = *state;
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

fn unit_of(x: u64) -> f32 {
    (x >> 40) as f32 * (1.0f32 / 16_777_216.0f32)
}

fn svc_unit(s: &mut Scene) -> f32 {
    unit_of(sm_next(&mut s.svc))
}

fn svc_sym(s: &mut Scene) -> f32 {
    2.0f32 * svc_unit(s) - 1.0f32
}

fn bits(f: f32) -> u32 {
    f.to_bits()
}

fn f(w: u32) -> f32 {
    f32::from_bits(w)
}

fn v3(w: &[u32]) -> FVector {
    FVector {
        x: f(w[0]),
        y: f(w[1]),
        z: f(w[2]),
    }
}

fn put3(out: &mut [u32], v: FVector) {
    out[0] = bits(v.x);
    out[1] = bits(v.y);
    out[2] = bits(v.z);
}

// `zero` and `blank_hit` serve the physic_* replays that `include!` this file.
#[allow(dead_code)]
fn zero() -> FVector {
    FVector {
        x: 0.0,
        y: 0.0,
        z: 0.0,
    }
}

#[allow(dead_code)]
fn blank_hit(time: f32) -> FCheckResult {
    FCheckResult {
        next: null_mut(),
        actor: null_mut(),
        location: zero(),
        normal: zero(),
        primitive: null_mut(),
        time,
        item: -1,
    }
}

fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h = 1_469_598_103_934_665_603u64;
    for &c in bytes {
        h ^= u64::from(c);
        h = h.wrapping_mul(1_099_511_628_211);
    }
    h
}

fn class_of(s: &Scene, p: usize) -> Option<u32> {
    if p == 0 {
        return None;
    }
    if p == s.subj {
        return Some(s.subj_class);
    }
    // The original motion harness replaces mover pool entries' class with AMover (an AActor child).
    s.pool.iter().position(|&q| q == p).map(|k| {
        if s.motion_mover_pool[k] {
            0
        } else {
            s.pool_class[k]
        }
    })
}

fn pidx(s: &Scene, p: usize) -> i32 {
    s.pool.iter().position(|&q| q == p).map_or(-1, |k| k as i32)
}

fn lg(s: &mut Scene, text: String) {
    s.log.push_str(&text);
}

// Class codes: 0 AActor, 1 APawn, 2 APlayerPawn, 3 ADecoration, 4 ACarcass.
fn is_a_impl(s: &Scene, obj: usize, class: i32) -> i32 {
    if class == 4 {
        return i32::from(obj == s.subj && s.motion_action == 0);
    }
    if class == 5 {
        return i32::from(
            s.pool
                .iter()
                .position(|&p| p == obj && p != 0)
                .is_some_and(|k| s.motion_mover_pool[k]),
        );
    }
    let Some(code) = class_of(s, obj) else {
        return 0;
    };
    let ok = match class {
        0 => code == 1 || code == 2,
        1 => code == 2,
        2 => code == 3 || code == 4,
        3 => code == 4,
        _ => false,
    };
    i32::from(ok)
}

fn scripted_hit(s: &mut Scene, hit: &mut FCheckResult) {
    let t0 = svc_unit(s);
    let nx = svc_sym(s);
    let ny = svc_sym(s);
    let nz = svc_sym(s);
    let lx = svc_unit(s);
    let ly = svc_unit(s);
    let lz = svc_unit(s);
    let x = sm_next(&mut s.svc);
    let t = if x.is_multiple_of(10) { 1.0 } else { t0 };
    let a = if x.is_multiple_of(4) && t >= 1.0 {
        0
    } else {
        s.pool[((x >> 8) % 3) as usize]
    };
    hit.time = t;
    hit.normal = FVector {
        x: nx,
        y: ny,
        z: nz,
    };
    hit.location = FVector {
        x: lx,
        y: ly,
        z: lz,
    };
    hit.actor = a as *mut c_void;
    let line = format!(
        "hit {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {}\n",
        bits(t),
        bits(nx),
        bits(ny),
        bits(nz),
        bits(lx),
        bits(ly),
        bits(lz),
        pidx(s, a)
    );
    lg(s, line);
}

fn is_probing_impl(s: &mut Scene) -> i32 {
    let ret = (sm_next(&mut s.svc) & 1) as i32;
    lg(s, format!("is_probing {ret}\n"));
    ret
}

fn app_frand_impl(s: &mut Scene) -> f32 {
    let u = svc_unit(s);
    lg(s, format!("app_frand {:08x}\n", bits(u)));
    u
}

unsafe fn cyl_impl(s: &mut Scene, actor: usize) -> FVector {
    let a = unsafe { &*(actor as *const AActor) };
    let v = FVector {
        x: a.collision_radius,
        y: a.collision_radius,
        z: a.collision_height,
    };
    lg(
        s,
        format!(
            "cyl_extent {:08x} {:08x} {:08x}\n",
            bits(v.x),
            bits(v.y),
            bits(v.z)
        ),
    );
    v
}

fn bsp_impl(s: &mut Scene, radius: f32) -> i32 {
    let d = sm_next(&mut s.svc) % 3;
    let code = match d {
        0 => 2,
        1 => 1,
        _ => 0,
    };
    lg(s, format!("bsp_surf {:08x} {code}\n", bits(radius)));
    i32::from(d == 0)
}

fn rot_impl(s: &mut Scene) -> FVector {
    let x = svc_sym(s);
    let y = svc_sym(s);
    let z = svc_sym(s);
    lg(
        s,
        format!(
            "rot_vector {:08x} {:08x} {:08x}\n",
            bits(x),
            bits(y),
            bits(z)
        ),
    );
    FVector { x, y, z }
}

fn move_impl(s: &mut Scene, delta: FVector, rot: FRotator, hit: &mut FCheckResult) -> i32 {
    let ret = i32::from(sm_next(&mut s.svc).is_multiple_of(4));
    lg(
        s,
        format!(
            "move {:08x} {:08x} {:08x} {} {} {} {}\n",
            bits(delta.x),
            bits(delta.y),
            bits(delta.z),
            rot.pitch,
            rot.yaw,
            rot.roll,
            ret
        ),
    );
    if ret == 0 {
        scripted_hit(s, hit);
    }
    ret
}

#[allow(clippy::too_many_arguments)] // mirrors the harness `hook_slc` signature
fn slc_impl(
    s: &mut Scene,
    hit: &mut FCheckResult,
    end: FVector,
    start: FVector,
    trace: i32,
    extent: FVector,
    source: i32,
    source_is_null: bool,
) -> i32 {
    let ret = i32::from(sm_next(&mut s.svc).is_multiple_of(3));
    lg(
        s,
        format!(
            "slc {} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {}\n",
            i32::from(trace == TRACE_ALL_BLOCKING),
            bits(end.x),
            bits(end.y),
            bits(end.z),
            bits(start.x),
            bits(start.y),
            bits(start.z),
            bits(extent.x),
            bits(extent.y),
            bits(extent.z),
            ret
        ),
    );
    lg(
        s,
        format!("slc_source {source} {}\n", source_is_null as i32),
    );
    if ret == 0 {
        scripted_hit(s, hit);
    }
    ret
}

thread_local! {
    // Lets `set_physics_preserves_motion_after_reentrant_base_callback`
    // (physic_dispatch.rs) redirect the shared `t_base_change` hook to a
    // reentrant physics mutation, instead of the fixture's log-and-reset
    // behavior, without a second `Hp2ActorServices` publish (the table is
    // process-global).
    static MUTATE_PHYSICS_ON_BASE_CHANGE: Cell<bool> = const { Cell::new(false) };
}
/// `Hp2ActorServices::actor_event_base_change`: SetBase's notify hook, replaying
/// the harness's unconditional `set_base <pidx>` log line. `actor::set_base`
/// writes `Base` before firing this event, so the destination is read back
/// here, then the field is reset to null — matching the harness's `SetBase`
/// override, which never writes `Base` at all, so every later production
/// guard check (`new_base != Base`) sees the same baseline the real engine
/// would. The one record that needs `Base` non-null going in is `run_case`'s
/// literal `"mount"` case, whose `hit.actor` is null: without a non-null
/// `Base` already in place, `mount`'s own `set_base` guard would see
/// `null != null` and skip the call, dropping the log line the original
/// engine always emits. `run_case` seeds a local zeroed buffer into the
/// actor's `Base` for that one record, right before dispatching to `mount`;
/// every other call site (including the swim/walk chains that reach `mount`
/// through `step_up`) passes a real non-null target, so the guard already
/// opens on its own and no seeding is needed there.
unsafe extern "C" fn t_base_change(actor: *mut c_void) -> i32 {
    if MUTATE_PHYSICS_ON_BASE_CHANGE.with(Cell::get) {
        unsafe { (*(actor as *mut AActor)).physics = 2 };
        return 0;
    }
    with(|s| {
        let a = unsafe { &mut *(actor as *mut AActor) };
        let new_base = a.base as usize;
        lg(s, format!("set_base {}\n", pidx(s, new_base)));
        a.base = null_mut();
    });
    0
}

