/// `Hp2ActorServices::mesh_collision_extent`: GetCylinderExtent's shape branch,
/// replaying the harness's radius/height `cyl_extent` log line. Every subject
/// actor is forced into the shape branch via a non-null `Mesh` so the
/// radius/height fallback the harness used is reproduced exactly.
unsafe extern "C" fn t_mesh_collision_extent(
    _mesh: *mut c_void,
    actor: *mut c_void,
    out: *mut c_void,
) -> i32 {
    let v = with(|s| unsafe { cyl_impl(s, actor as usize) });
    unsafe { *(out as *mut FVector) = v };
    0
}

unsafe extern "C" fn m_bsp(_hit: *const FCheckResult, radius: f32) -> i32 {
    with(|s| bsp_impl(s, radius))
}

unsafe extern "C" fn m_rot(_rot: *const FRotator, out: *mut FVector) {
    let v = with(rot_impl);
    unsafe { *out = v };
}

unsafe extern "C" fn m_move(
    _actor: *mut c_void,
    delta: *const FVector,
    rot: *const FRotator,
    hit: *mut FCheckResult,
) -> i32 {
    let (delta, rot) = unsafe { (*delta, *rot) };
    with(|s| move_impl(s, delta, rot, unsafe { &mut *hit }))
}

unsafe extern "C" fn m_slc(
    actor: *mut c_void,
    hit: *mut FCheckResult,
    end: *const FVector,
    start: *const FVector,
    trace: i32,
    extent: *const FVector,
) -> i32 {
    let (end, start, extent) = unsafe { (*end, *start, *extent) };
    with(|s| {
        let source = pidx(s, actor as usize);
        slc_impl(
            s,
            unsafe { &mut *hit },
            end,
            start,
            trace,
            extent,
            source,
            actor.is_null(),
        )
    })
}

unsafe extern "C" fn m_slc_no_source(
    _actor: *mut c_void,
    hit: *mut FCheckResult,
    end: *const FVector,
    start: *const FVector,
    trace: i32,
    extent: *const FVector,
) -> i32 {
    let (end, start, extent) = unsafe { (*end, *start, *extent) };
    with(|s| slc_impl(s, unsafe { &mut *hit }, end, start, trace, extent, -1, true))
}

