unsafe extern "C" fn m_rotation_from_vector(vector: *const FVector, out: *mut FRotator) {
    let v = unsafe { *vector };
    let angle_scale = f64::from(u16::MAX);
    let denom = f64::from(2.0_f32 * std::f32::consts::PI);
    let planar = f64::from(v.x * v.x + v.y * v.y).sqrt();
    unsafe {
        (*out).yaw = (f64::from(v.y).atan2(f64::from(v.x)) * angle_scale / denom) as i32;
        (*out).pitch = (f64::from(v.z).atan2(planar) * angle_scale / denom) as i32;
        (*out).roll = 0;
    }
}

