unsafe extern "C" fn m_mesh_bone_coords(
    _mesh: *mut c_void,
    _owner: *mut c_void,
    _bone: i32,
    out: *mut c_void,
) {
    if out.is_null() {
        return;
    }
    let v = with(|s| s.trailer_bone_coords);
    let coords = hp2_abi::FCoords {
        origin: FVector {
            x: v[0],
            y: v[1],
            z: v[2],
        },
        x_axis: FVector {
            x: v[3],
            y: v[4],
            z: v[5],
        },
        y_axis: FVector {
            x: v[6],
            y: v[7],
            z: v[8],
        },
        z_axis: FVector {
            x: v[9],
            y: v[10],
            z: v[11],
        },
    };
    unsafe { out.cast::<hp2_abi::FCoords>().write_unaligned(coords) };
}

