fn arg_words(name: &str) -> usize {
    match name {
        "calc_velocity" => 9,
        "mount" => 3,
        "step_up" => 9,
        "process_hit_wall" => 4,
        "process_landed" => 6,
        other => panic!("unknown function {other}"),
    }
}

fn pool_or_null(pool: &[usize; 3], idx: u32) -> *mut c_void {
    let i = idx as i32;
    if i < 0 {
        null_mut()
    } else {
        pool[i as usize] as *mut c_void
    }
}

fn run_case(name: &str, seed: u64, w: &[u32]) -> [u32; OUT_WORDS] {
    actor_services_mock::publish_with_mesh_and_base_change(t_mesh_collision_extent, t_base_change);
    // Zeroed, 8 KiB-equivalent object memory, matching the harness memset.
    let mut subj = vec![0u64; 1024];
    let mut zone = vec![0u64; 1024];
    let mut pool = [vec![0u64; 1024], vec![0u64; 1024], vec![0u64; 1024]];
    let mut base_sentinel = vec![0u64; 1024];
    let base_sentinel_p = base_sentinel.as_mut_ptr() as usize;
    let subj_p = subj.as_mut_ptr() as usize;
    let zone_p = zone.as_mut_ptr() as usize;
    let pool_p = [
        pool[0].as_mut_ptr() as usize,
        pool[1].as_mut_ptr() as usize,
        pool[2].as_mut_ptr() as usize,
    ];

    with(|s| {
        s.svc = seed;
        s.log.clear();
        s.subj = subj_p;
        s.subj_class = w[31];
        s.zone = zone_p;
        s.pool = pool_p;
        s.pool_class = [w[39], w[42], w[45]];
    });

    // SAFETY: each pointer addresses a zeroed buffer of at least the struct size,
    // and the buffers outlive every access below.
    unsafe {
        let z = zone_p as *mut AZoneInfo;
        (*z).zone_gravity = v3(&w[32..35]);
        (*z).zone_velocity = v3(&w[35..38]);
        (*z).set_b_bounce_velocity(w[38] != 0);
        for k in 0..3 {
            let d = pool_p[k] as *mut ADecoration;
            (*d).base.mass = f(w[40 + 3 * k]);
            (*d).set_b_pushable(w[41 + 3 * k] != 0);
        }

        let p = subj_p as *mut APawn;
        (*p).base.location = v3(&w[0..3]);
        (*p).base.rotation = FRotator {
            pitch: w[3] as i32,
            yaw: w[4] as i32,
            roll: w[5] as i32,
        };
        (*p).base.velocity = v3(&w[6..9]);
        (*p).base.acceleration = v3(&w[9..12]);
        (*p).base.physics = w[12] as u8;
        (*p).base.set_b_is_pawn(w[13] != 0);
        (*p).base.set_b_just_teleported(w[14] != 0);
        (*p).set_b_is_walking(w[15] != 0);
        (*p).set_b_from_wall(w[16] != 0);
        (*p).destination = v3(&w[17..20]);
        (*p).accel_rate = f(w[20]);
        (*p).desired_speed = f(w[21]);
        (*p).max_step_height = f(w[22]);
        (*p).max_mount_height = f(w[23]);
        (*p).min_hit_wall = f(w[24]);
        (*p).base.collision_radius = f(w[25]);
        (*p).base.collision_height = f(w[26]);
        (*p).base.mass = f(w[27]);
        (*p).base.buoyancy = f(w[28]);
        (*(subj_p as *mut ADecoration)).num_landings = w[29] as i32;
        (*(subj_p as *mut ACarcass)).set_b_sliding_carcass(w[30] != 0);
        (*p).base.region.zone = zone_p as *mut c_void;
        if name == "mount" {
            (*p).base.base = base_sentinel_p as *mut c_void;
        }
        (*p).base.mesh = base_sentinel_p as *mut c_void;
        (*p).base.collide_type = CT_SHAPE;
    }

    let mut hit = FCheckResult {
        next: null_mut(),
        actor: pool_or_null(&pool_p, w[55]),
        location: v3(&w[52..55]),
        normal: v3(&w[49..52]),
        primitive: null_mut(),
        time: f(w[48]),
        item: -1,
    };
    let arg = &w[ARG0..];
    let subj_apawn = subj_p as *mut APawn;
    let ret = unsafe {
        match name {
            "calc_velocity" => {
                physic::calc_velocity(
                    subj_apawn,
                    &SERVICES,
                    v3(&arg[0..3]),
                    f(arg[3]),
                    f(arg[4]),
                    f(arg[5]),
                    arg[6] as i32,
                    arg[7] as i32,
                    arg[8] as i32,
                )
                .expect("checked physics fixture");
                0
            }
            "mount" => u32::from(
                physic::mount(subj_apawn, &SERVICES, v3(&arg[0..3]), &mut hit)
                    .expect("checked physics fixture"),
            ),
            "step_up" => {
                physic::step_up(
                    subj_apawn,
                    &SERVICES,
                    v3(&arg[0..3]),
                    v3(&arg[3..6]),
                    v3(&arg[6..9]),
                    &mut hit,
                )
                .expect("checked physics fixture");
                0
            }
            "process_hit_wall" => {
                physic::process_hit_wall(
                    subj_p as *mut AActor,
                    &SERVICES,
                    v3(&arg[0..3]),
                    pool_p[arg[3] as usize] as *mut c_void,
                )
                .expect("checked physics fixture");
                0
            }
            "process_landed" => {
                physic::process_landed(
                    subj_p as *mut AActor,
                    &SERVICES,
                    v3(&arg[0..3]),
                    pool_or_null(&pool_p, arg[3]),
                    f(arg[4]),
                    arg[5] as i32,
                )
                .expect("checked physics fixture");
                0
            }
            other => panic!("unknown function {other}"),
        }
    };

    let mut out = [0u32; OUT_WORDS];
    // SAFETY: same buffers as above, still alive.
    unsafe {
        let p = subj_p as *const APawn;
        let a = &(*p).base;
        put3(&mut out[0..3], a.location);
        out[3] = a.rotation.pitch as u32;
        out[4] = a.rotation.yaw as u32;
        out[5] = a.rotation.roll as u32;
        put3(&mut out[6..9], a.velocity);
        put3(&mut out[9..12], a.acceleration);
        out[12] = u32::from(a.physics);
        out[13] = u32::from(a.b_is_pawn());
        out[14] = u32::from(a.b_just_teleported());
        out[15] = u32::from((*p).b_is_walking());
        out[16] = u32::from((*p).b_from_wall());
        put3(&mut out[17..20], (*p).destination);
        out[20] = bits((*p).accel_rate);
        out[21] = bits((*p).desired_speed);
        out[22] = bits((*p).max_step_height);
        out[23] = bits((*p).max_mount_height);
        out[24] = bits((*p).min_hit_wall);
        out[25] = bits(a.collision_radius);
        out[26] = bits(a.collision_height);
        out[27] = bits(a.mass);
        out[28] = bits(a.buoyancy);
        out[29] = (*(subj_p as *const ADecoration)).num_landings as u32;
        out[30] = u32::from((*(subj_p as *const ACarcass)).b_sliding_carcass());
        out[31] = with(|s| s.subj_class);

        let z = zone_p as *const AZoneInfo;
        put3(&mut out[32..35], (*z).zone_gravity);
        put3(&mut out[35..38], (*z).zone_velocity);
        out[38] = u32::from((*z).b_bounce_velocity());
    }
    out[39] = bits(hit.time);
    put3(&mut out[40..43], hit.normal);
    put3(&mut out[43..46], hit.location);
    out[46] = with(|s| pidx(s, hit.actor as usize)) as u32;
    out[47] = ret;
    let digest = with(|s| fnv1a(s.log.as_bytes()));
    let len = with(|s| s.log.len());
    out[48] = (digest >> 32) as u32;
    out[49] = digest as u32;
    out[50] = len as u32;
    // Keep the backing storage alive until every read above has finished.
    drop((subj, zone, pool));
    out
}

#[test]
fn physic_scripted_matches_original() {
    assert!(std::mem::size_of::<APawn>() <= 8192);
    assert!(std::mem::size_of::<AZoneInfo>() <= 8192);

    let text = include_str!("fixtures/physic_scripted.txt");
    let mut per_fn: BTreeMap<&str, usize> = BTreeMap::new();
    let mut total = 0usize;
    let mut no_hit = 0usize;
    let mut null_actor = 0usize;

    for (rec, line) in text.lines().enumerate() {
        let toks: Vec<&str> = line.split_whitespace().collect();
        let sep = toks
            .iter()
            .position(|t| *t == "|")
            .unwrap_or_else(|| panic!("record {rec}: missing separator"));
        let name = toks[0];
        let seed = u64::from_str_radix(toks[1], 16).expect("seed");
        let input: Vec<u32> = toks[2..sep]
            .iter()
            .map(|t| u32::from_str_radix(t, 16).expect("input word"))
            .collect();
        let expect: Vec<u32> = toks[sep + 1..]
            .iter()
            .map(|t| u32::from_str_radix(t, 16).expect("output word"))
            .collect();
        assert_eq!(
            input.len(),
            ARG0 + arg_words(name),
            "record {rec} ({name}): input width"
        );
        assert_eq!(
            expect.len(),
            OUT_WORDS,
            "record {rec} ({name}): output width"
        );

        let got = run_case(name, seed, &input);
        if let Some(i) = (0..OUT_WORDS).find(|&i| got[i] != expect[i]) {
            panic!(
                "record {rec} {name} seed {seed:016x}: word {i} expected {:08x} got {:08x}",
                expect[i], got[i]
            );
        }

        *per_fn.entry(name).or_default() += 1;
        total += 1;
        if expect[39] == 0x3f80_0000 {
            no_hit += 1;
        }
        if expect[46] == u32::MAX {
            null_actor += 1;
        }
    }

    assert_eq!(total, 6000);
    for name in FN_NAMES {
        assert_eq!(per_fn.get(name).copied(), Some(1200), "{name} case count");
    }
    assert!(no_hit > 0, "no-hit (Time == 1) coverage");
    assert!(null_actor > 0, "NULL hit-actor coverage");
}

